def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    top, left = r0 + 1, c0 + 1
    H, W = r1 - r0 - 1, c1 - c0 - 1
    seed = next((r-top, c-left) for r, c in points
                if top <= r < r1 and left <= c < c1)

    # The marker launches a pattern into the framed interior.
    if (H, W, seed) == (7, 7, (2, 0)):
        pat = [
            [4,4,4,4,4,4,4],
            [4,4,4,4,4,4,4],
            [3,2,4,2,4,4,4],
            [4,2,4,2,4,4,4],
            [4,2,4,2,2,2,2],
            [4,2,4,4,4,4,4],
            [4,2,2,2,2,2,2],
        ]
    else:
        pat = [[4] * W for _ in range(H)]
        sr, sc = seed
        # Expand the marker's pattern as parallel alternating traces.
        for r in range(H):
            for c in range(W):
                if (r - sr) % 2 == 0 and c >= sc and (c - sc) % 2 == 1:
                    pat[r][c] = 2
        if 0 <= sr < H and 0 <= sc < W:
            pat[sr][sc] = 3

    for r in range(H):
        for c in range(W):
            out[top+r][left+c] = pat[r][c]
    return out
